// Demo support tickets. PRODUCTION: replace with webhook body from your support system.
const tickets = [
  { customerName: "Sarah Mitchell", email: "sarah@brightwavecoffee.com", subject: "Can't export my reports to PDF", message: "I've been trying to export my monthly reports to PDF but the button is greyed out. I'm on the Growth plan. This is blocking my client reporting.", source: "email" },
  { customerName: "Marcus Chen", email: "marcus@fitlifestudios.com", subject: "Feature request: dark mode", message: "Would love to see a dark mode option in the dashboard. My team works late and the bright white is hard on the eyes.", source: "form" },
  { customerName: "Diana Torres", email: "diana@greenscapellc.com", subject: "Double charged this month", message: "I was charged twice for my subscription this month. Order #12345 and #12346 are identical. Please refund one.", source: "email" }
];
return tickets.map(t => ({ json: { ...t, EventKey: "ticket:" + t.email + ":" + new Date().toISOString().slice(0,10) } }));

const t = $json;
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(t.email || ''));
const ok = emailOk && t.subject && String(t.subject).length >= 3 && String(t.message || '').length > 10;
if (!ok) return { json: { Timestamp: new Date().toISOString(), EventKey: t.EventKey || 'unknown',
  Workflow: 'support-triage', Status: 'rejected_invalid_ticket', Reason: 'bad email/subject/message' } };
return { json: { ...t, input_valid: true } };

const raw = $json.content?.parts?.filter(p => !p.thought).map(p => p.text || '').join('') ?? $json.text ?? '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let data = null;
for (const c of (cleaned.match(/\{[\s\S]*\}/g) || []).reverse()) {
  try { const p = JSON.parse(c); if (p && p.category) { data = p; break; } } catch(e){}
}
const ticket = $('Validate Ticket').item.json;
if (!data) return { json: { ...ticket, parse_ok: false, error: 'AI output unparseable',
  category: 'general', priority: 'normal', suggestedResponse: 'Thanks for reaching out. We\'ll get back to you soon.', routing: 'support', confidence: 0.5 } };
const confidence = typeof data.confidence === 'number' ? data.confidence : 0.7;
return { json: { ...ticket, ...data, confidence, parse_ok: true } };

